// Reads "proposal viewed" notifications from the proposal system and works out what changed.
const TEST = $execution.mode !== 'production';
const ONLY = TEST ? /EECOL/i : null; // a test run touches only the EECOL proposal
const seen = $('Get seen views').all().map(i => i.json);
const doneMsg = new Set(seen.map(r => String(r.message_id || '')));
const prevViews = {};
for (const r of seen) if (r.bid_link) prevViews[r.bid_link] = Math.max(prevViews[r.bid_link] || 0, Number(r.views) || 0);
const strip = h => String(h || '').replace(/<li[^>]*>/gi, '\n').replace(/<br\s*\/?>|<\/p>|<\/div>/gi, '\n').replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&');
const parseT = s => { const m = /(\d\d)\/(\d\d)\/(\d{4}) - (\d\d):(\d\d) (AM|PM)/.exec(s); if (!m) return null;
  let h = Number(m[4]) % 12; if (m[6] === 'PM') h += 12; return Date.UTC(+m[3], +m[1] - 1, +m[2], h, +m[5]); };
const fmt = t => { const d = new Date(t); const h = d.getUTCHours(); return d.toISOString().slice(0, 10) + ' ' + ((h % 12) || 12) + ':' + String(d.getUTCMinutes()).padStart(2, '0') + (h < 12 ? ' am' : ' pm'); };
const DAY = 86400000;
const best = {}; // one result per proposal per run: the notification with the most views
for (const m of $('Get recent mail').all().map(i => i.json)) {
  const from = String((m.from && m.from.emailAddress && m.from.emailAddress.address) || '').toLowerCase();
  const subj = String(m.subject || '');
  if (from !== 'notifications@myanagoclean.com' || !/Has Been Viewed/i.test(subj)) continue;
  if (ONLY && !ONLY.test(subj)) continue;
  const id = String(m.id || '');
  if (!id || doneMsg.has(id)) continue;
  const html = String((m.body && m.body.content) || '');
  const text = strip(html);
  const link = (/Bid Link:\s*<a href="([^"]+)"/i.exec(html) || /Bid Link:\s*(https?:\S+)/i.exec(text) || [])[1];
  if (!link) continue;
  const company = (/Proposal for (.+?) Has Been Viewed/i.exec(subj) || [])[1] || '';
  const kind = (/Your (\w+) Proposal for/i.exec(subj) || [])[1] || '';
  const ol = (/<ol>([\s\S]*?)<\/ol>/i.exec(html) || [])[1] || '';
  const times = [...ol.matchAll(/<li>([^<]+)<\/li>/gi)].map(x => parseT(x[1])).filter(Boolean).sort((a, b) => a - b);
  const count = Number((/accessed (\d+) time/i.exec(text) || [])[1]) || times.length;
  if (!times.length) { const t = parseT((/most recent access on ([^.]+)/i.exec(text) || [])[1] || ''); if (t) times.push(t); }
  const dm = (/Decision Maker([\s\S]*?)(Walk-Thru Contact|The Anago Team)/i.exec(text) || [])[1] || '';
  const dmName = ((/Name:\s*([^\n]+)/.exec(dm) || [])[1] || '').trim();
  const dmEmail = ((/Email:\s*([^\s\n]+@[^\s\n]+)/.exec(dm) || [])[1] || '').trim().toLowerCase();
  const dmPhone = ((/Phone:\s*([^\n]+)/.exec(dm) || [])[1] || '').trim();
  const cur = best[link];
  if (cur && cur.views >= count) { cur.message_ids.push(id); continue; }
  best[link] = { bid_link: link, company, kind, views: count, times, dm_name: dmName, dm_email: dmEmail, dm_phone: dmPhone, message_ids: (cur ? cur.message_ids : []).concat(id) };
}
const out = [];
for (const v of Object.values(best)) {
  const prev = prevViews[v.bid_link] || 0;
  if (v.views <= prev) continue; // repeat of a notification already handled
  // Call when: first view we know of, or any new open comes 3+ days after the open before it.
  let gapDays = 0;
  for (let i = Math.max(prev, 1); i < v.times.length; i++) gapDays = Math.max(gapDays, (v.times[i] - v.times[i - 1]) / DAY);
  const last = v.times.length ? v.times[v.times.length - 1] : null;
  const task = prev === 0 || gapDays >= 3;
  const why = gapDays >= 3 ? 'came back to the proposal after ' + Math.floor(gapDays) + ' days' : (v.views <= 1 ? 'opened the proposal for the first time' : 'has opened the proposal ' + v.views + ' times');
  out.push({ json: Object.assign(v, {
    prev_views: prev, task, why,
    last_date: last ? new Date(last).toISOString().slice(0, 10) : $now.setZone('America/Winnipeg').toISODate(),
    last_text: last ? fmt(last) : '',
    history: v.times.map(fmt).join('<br>'),
    message_id: v.message_ids.join(','),
  }) });
}
return out;

// Find the open deal for this proposal: by the proposal link first, then by the decision maker's email.
const v = $('Parse views').item.json;
const byLink = ((($('Find deal by link').item.json.data || {}).items) || []).map(x => x.item).filter(d => d && d.status === 'open');
const person = (((($('Find person').item.json.data || {}).items) || [])[0] || { item: {} }).item;
let deal = null, via = 'none';
if (byLink.length) { const d = byLink[0]; deal = { id: d.id, stage_id: d.stage && d.stage.id, person_id: d.person && d.person.id }; via = 'proposal link'; }
else if (person.id) {
  const ds = (Array.isArray($json.data) ? $json.data : []).filter(d => d.status === 'open')
    .sort((a, b) => ((a.pipeline_id === 1 ? 0 : 1) - (b.pipeline_id === 1 ? 0 : 1)) || String(b.update_time).localeCompare(String(a.update_time)));
  if (ds[0]) { const d = ds[0]; deal = { id: d.id, stage_id: d.stage_id, person_id: (d.person_id && d.person_id.value) || d.person_id || person.id }; via = 'decision maker email'; }
}
return { json: Object.assign({}, v, { deal_id: deal ? deal.id : null, stage_id: deal ? deal.stage_id : null, person_id: (deal && deal.person_id) || person.id || null, org_id: (person.organization && person.organization.id) || null, matched_by: via }) };

